/**
 * Request body validation without eval/new Function so it runs in
 * Cloudflare Workers (which forbids code generation from strings).
 * Each validator is a plain TypeScript function — no AJV, no JSON Schema.
 */
import type { Context, Next } from "hono";
import { isWorkersAiModelId } from "../config/deployment";

type Validator<T> = (body: unknown) => { ok: true; value: T } | { ok: false; errors: string[] };

export function validateBody<T>(validator: Validator<T>) {
  return async (c: Context, next: Next) => {
    // ボディストリームは一度しか読めないため、content-type で先に分岐する。
    // （json() 失敗後の parseBody() フォールバックは、消費済みストリームの再読取に
    // なり常に失敗していた — htmx/ネイティブフォームのログイン不能の原因）
    const contentType = (c.req.header("content-type") ?? "").toLowerCase();
    let body: unknown;
    try {
      if (
        contentType.includes("application/x-www-form-urlencoded") ||
        contentType.includes("multipart/form-data")
      ) {
        body = await c.req.parseBody();
      } else {
        body = await c.req.json();
      }
    } catch {
      return c.json({ error: { code: "invalid_body", message: "request body must be valid JSON or form data" } }, 400);
    }
    const result = validator(body);
    if (!result.ok) {
      return c.json(
        { error: { code: "validation_failed", message: "request body is invalid", details: result.errors } },
        400
      );
    }
    c.set("body", result.value);
    await next();
  };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

// ── Validators ───────────────────────────────────────────────────────────────

export const credentialsSchema: Validator<{ email: string; password: string }> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  const errors: string[] = [];
  if (typeof body.email !== "string" || !EMAIL_RE.test(body.email) || body.email.length > 320)
    errors.push("email must be a valid email address (max 320 chars)");
  if (typeof body.password !== "string" || body.password.length < 8 || body.password.length > 1024)
    errors.push("password must be a string between 8 and 1024 characters");
  if (errors.length) return { ok: false, errors };
  return { ok: true, value: { email: body.email as string, password: body.password as string } };
};

export const profileUpdateSchema: Validator<{ email: string; password?: string }> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  const errors: string[] = [];
  if (typeof body.email !== "string" || !EMAIL_RE.test(body.email) || body.email.length > 320)
    errors.push("email must be a valid email address (max 320 chars)");
  if (body.password !== undefined) {
    if (typeof body.password !== "string" || body.password.length < 8 || body.password.length > 1024)
      errors.push("password must be a string between 8 and 1024 characters");
  }
  if (errors.length) return { ok: false, errors };
  return { ok: true, value: { email: body.email as string, password: body.password as string | undefined } };
};

export const inspectSchema: Validator<Record<string, unknown>> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  const errors: string[] = [];
  if (!Array.isArray(body.files) || body.files.length === 0)
    errors.push("files must be a non-empty array");
  else if (body.files.some((f: unknown) => !isObj(f) || typeof (f as any).path !== "string" || typeof (f as any).content !== "string"))
    errors.push("each file must have string path and content");
  if (errors.length) return { ok: false, errors };
  return { ok: true, value: body };
};

export const settingsSchema: Validator<Record<string, unknown>> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  if (body.registrationEnabled !== undefined && typeof body.registrationEnabled !== "boolean")
    return { ok: false, errors: ["registrationEnabled must be a boolean"] };
  return { ok: true, value: body };
};

export const codeSessionCreateSchema: Validator<{
  repoUrl?: string;
  branch?: string;
  baseBranch?: string;
  title: string;
  instruction: string;
}> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  const errors: string[] = [];
  // repoUrl は任意（選択リポジトリを使う場合は省略可）。指定時は文字列であること。
  if (body.repoUrl !== undefined && typeof body.repoUrl !== "string")
    errors.push("repoUrl must be a string");
  if (typeof body.title !== "string" || body.title.length === 0)
    errors.push("title must be a non-empty string");
  if (typeof body.instruction !== "string" || body.instruction.length === 0)
    errors.push("instruction must be a non-empty string");
  if (errors.length) return { ok: false, errors };
  return { ok: true, value: body as { repoUrl?: string; branch?: string; baseBranch?: string; title: string; instruction: string } };
};

export const codeSessionActionSchema: Validator<Record<string, unknown>> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  return { ok: true, value: body };
};

export const modelSchema: Validator<{ model: string | null }> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  if (body.model !== null && typeof body.model !== "string")
    return { ok: false, errors: ["model must be a string or null"] };
  if (typeof body.model === "string" && !isWorkersAiModelId(body.model))
    return { ok: false, errors: [`"${body.model}" is not a valid Workers AI model id`] };
  return { ok: true, value: body as { model: string | null } };
};

/**
 * テキスト生成 + Embedding の保存。htmx フォームからも送られる。
 * present なフィールドのみ適用し、空文字はデフォルトに戻す。
 */
export const userModelsSchema: Validator<{ model?: string; embeddingModel?: string }> = (body) => {
  if (!isObj(body)) return { ok: false, errors: ["body must be an object"] };
  const errors: string[] = [];
  const value: { model?: string; embeddingModel?: string } = {};
  for (const field of ["model", "embeddingModel"] as const) {
    const raw = body[field];
    if (raw === undefined || raw === null) continue;
    if (typeof raw !== "string") {
      errors.push(`${field} must be a string`);
      continue;
    }
    if (raw !== "" && !isWorkersAiModelId(raw)) {
      errors.push(`"${raw}" is not a valid Workers AI model id (${field})`);
      continue;
    }
    value[field] = raw;
  }
  if (errors.length) return { ok: false, errors };
  return { ok: true, value };
};
